using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() now manages its own transactions.
    // Wrapping it in a user transaction throws. Remove the transaction wrapper.
    async Task ApplyMigrationsAsync(AppDbContext db)
    {
        await db.Database.MigrateAsync();
    }
}

